package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type LedgerRec struct {
	BrBranch string
	BrAcct   string
	BrType   string
	BrAmt    decimal.Decimal
}

var WsEofFlag string
var WsFirstFlag string
var WsPrevBranch string
var WsPrevAcct string
var WsBal decimal.Decimal
var WsBranchTot decimal.Decimal
var WsGrandTot decimal.Decimal
var WsSkipped int64
var WsAmtEd string
var WsBalEd string
var WsTotEd string

var ledgerRec LedgerRec

func padRight(s string, n int) string {
	if len(s) >= n {
		return s[:n]
	}
	return s + strings.Repeat(" ", n-len(s))
}

func formatEdited(pic string, val decimal.Decimal) string {
	signNeeded := false
	signChar := ' '
	remaining := pic
	if len(pic) > 0 && pic[0] == '-' {
		signNeeded = true
		if val.IsNegative() {
			signChar = '-'
		} else {
			signChar = ' '
		}
		remaining = pic[1:]
	} else if len(pic) > 0 && pic[0] == '+' {
		signNeeded = true
		if val.IsNegative() {
			signChar = '-'
		} else {
			signChar = '+'
		}
		remaining = pic[1:]
	}

	var intPic, fracPic string
	if idx := strings.Index(remaining, "."); idx >= 0 {
		intPic = remaining[:idx]
		fracPic = remaining[idx+1:]
	} else {
		intPic = remaining
		fracPic = ""
	}
	fracLen := 0
	for _, c := range fracPic {
		if c == 'Z' || c == '9' || c == '0' {
			fracLen++
		}
	}
	intDigitCount := 0
	for _, c := range intPic {
		if c == 'Z' || c == '9' || c == '0' {
			intDigitCount++
		}
	}

	absVal := val.Abs()

	// integer part digits
	intPartDec := absVal.Truncate(0)
	intStr := intPartDec.StringFixed(0)
	// StringFixed(0) for 0 gives "0"
	if intStr == "" {
		intStr = "0"
	}
	// handle overflow: keep low-order digits
	if len(intStr) > intDigitCount {
		intStr = intStr[len(intStr)-intDigitCount:]
	} else if len(intStr) < intDigitCount {
		intStr = strings.Repeat("0", intDigitCount-len(intStr)) + intStr
	}
	// first non-zero index
	firstNonZero := -1
	for i, c := range intStr {
		if c != '0' {
			firstNonZero = i
			break
		}
	}

	// build integer formatted part
	var intOut []rune
	digitIdx := 0
	for _, pc := range intPic {
		if pc == 'Z' || pc == '9' {
			d := rune(intStr[digitIdx])
			var out rune
			if firstNonZero == -1 {
				// zero value
				if pc == 'Z' {
					out = ' '
				} else {
					out = d // '0'
				}
			} else {
				if digitIdx < firstNonZero && pc == 'Z' {
					out = ' '
				} else {
					out = d
				}
			}
			intOut = append(intOut, out)
			digitIdx++
		} else if pc == ',' {
			var out rune
			if firstNonZero == -1 {
				out = ' '
			} else {
				if digitIdx <= firstNonZero {
					out = ' '
				} else {
					out = ','
				}
			}
			intOut = append(intOut, out)
		} else {
			intOut = append(intOut, pc)
		}
	}

	// fractional part
	var fracOut string
	if fracLen > 0 {
		scaled := absVal.Shift(int32(fracLen)).Truncate(0)
		scaledStr := scaled.StringFixed(0)
		if scaledStr == "" {
			scaledStr = "0"
		}
		// need at least fracLen digits for fractional part
		if len(scaledStr) < fracLen {
			scaledStr = strings.Repeat("0", fracLen-len(scaledStr)) + scaledStr
		}
		fracOut = scaledStr[len(scaledStr)-fracLen:]
		// ensure exactly fracLen
		if len(fracOut) < fracLen {
			fracOut = strings.Repeat("0", fracLen-len(fracOut)) + fracOut
		}
	}

	var result string
	if fracLen > 0 {
		result = string(intOut) + "." + fracOut
	} else {
		result = string(intOut)
	}
	if signNeeded {
		result = string(signChar) + result
	}
	// ensure width equals pic length (should already)
	if len(result) < len(pic) {
		result = strings.Repeat(" ", len(pic)-len(result)) + result
	} else if len(result) > len(pic) {
		result = result[len(result)-len(pic):]
	}
	return result
}

func formatAmt(v decimal.Decimal) string {
	return formatEdited("ZZ,ZZ9.99", v)
}
func formatBal(v decimal.Decimal) string {
	return formatEdited("-Z,ZZZ,ZZ9.99", v)
}
func formatTot(v decimal.Decimal) string {
	return formatEdited("-ZZZ,ZZZ,ZZ9.99", v)
}

func formatSkipped(v int64) string {
	// PIC 99 zero padded to 2
	s := fmt.Sprintf("%d", v)
	if len(s) > 2 {
		s = s[len(s)-2:]
	} else if len(s) < 2 {
		s = strings.Repeat("0", 2-len(s)) + s
	}
	return s
}

// file handling
var reader *bufio.Reader
var eofReached bool

func openInput() {
	f, err := os.Open("input.dat")
	if err != nil {
		// if file doesn't exist, treat as EOF
		eofReached = true
		WsEofFlag = "Y"
		return
	}
	reader = bufio.NewReader(f)
	eofReached = false
}

func readPara() {
	if eofReached {
		WsEofFlag = "Y"
		return
	}
	line, err := reader.ReadString('\n')
	if err != nil {
		// EOF, maybe partial line
		if len(line) == 0 {
			WsEofFlag = "Y"
			eofReached = true
			return
		}
		// process last line without newline
	} else {
		// strip trailing \n and \r
		line = strings.TrimRight(line, "\r\n")
	}
	// COBOL LINE SEQUENTIAL: pad with spaces to record length 14
	if len(line) < 14 {
		line = line + strings.Repeat(" ", 14-len(line))
	} else if len(line) > 14 {
		line = line[:14]
	}
	// parse fields
	ledgerRec.BrBranch = line[0:2]
	ledgerRec.BrAcct = line[2:6]
	ledgerRec.BrType = line[6:7]
	amtStr := line[7:14] // 7 digits
	// amtStr should be digits; parse as integer
	amtStr = strings.TrimSpace(amtStr)
	if amtStr == "" {
		amtStr = "0"
	}
	// keep only digits? Assume digits
	// If contains spaces, they were padding; but field is numeric digits only
	// Remove any non-digit? But spec says digits only.
	clean := ""
	for _, ch := range amtStr {
		if ch >= '0' && ch <= '9' {
			clean += string(ch)
		}
	}
	if clean == "" {
		clean = "0"
	}
	n, _ := decimal.NewFromString(clean)
	// implied V99 => shift -2
	ledgerRec.BrAmt = decimal.New(n.IntPart(), -2)
	if err != nil && len(line) == 0 {
		// already handled
	}
	// if we hit EOF after reading this line, next read will set done
	// Need to detect if the underlying ReadString returned io.EOF we already consumed line, next call will be EOF
	// We track by peeking? Simpler: if err != nil (io.EOF) we set a flag that next call is EOF, but current record is valid.
	// So if err != nil and we processed line, don't set INPUT-DONE yet.
	if err != nil {
		// Next read will be EOF, but for COBOL, AT END is only on next READ attempt beyond file.
		// Our current read succeeded (even if io.EOF with data), so WsEofFlag stays "N"
		// Mark that next read should be EOF
		// We will set eofReached after this successful read if the underlying error was EOF
		// Check if we are at EOF by trying to peek next byte? Instead set a flag to indicate next read is EOF
		// We'll set eofReached = true only after we know no more data.
		// For ReadString that returned EOF with data, the next call will return EOF with no data.
		// So we need to keep eofReached false for now but remember we are at end.
		// Approach: if err != nil (EOF), set a pendingEOF flag.
		// Simpler: set eofReached = false сейчас, but we can check if underlying file at EOF: next ReadString will return err != nil and len(line)==0.
		// To handle correctly, we don't set eofReached now; we let next call handle.
		// However the reader may have consumed all; next call will be EOF.
		// We need to know if this was the last line with EOF, we should not set INPUT-DONE yet.
		// So do nothing.
		WsEofFlag = "N"
		// We need to remember that the underlying reader may have hit EOF but we already got line.
		// The next call will detect EOF properly.
		// To avoid missing, we check if err != nil : the file is at EOF, next read will be empty. We can set a flag pending.
		// We'll use a boolean pendingEOF
		pendingEOF = true
		return
	}
	WsEofFlag = "N"
}

var pendingEOF bool

func readPara2() {
	if pendingEOF {
		// we already consumed last line, next read should check if more data
		// Actually pendingEOF means last read hit EOF with data; next read should be EOF.
		// So we attempt to read again; if it fails, set done.
	}
	if eofReached {
		WsEofFlag = "Y"
		return
	}
	line, err := reader.ReadString('\n')
	if err != nil {
		if len(line) == 0 {
			WsEofFlag = "Y"
			eofReached = true
			return
		}
		line = strings.TrimRight(line, "\r\n")
		if len(line) < 14 {
			line = line + strings.Repeat(" ", 14-len(line))
		} else if len(line) > 14 {
			line = line[:14]
		}
		ledgerRec.BrBranch = line[0:2]
		ledgerRec.BrAcct = line[2:6]
		ledgerRec.BrType = line[6:7]
		amtStr := line[7:14]
		amtStr = strings.TrimSpace(amtStr)
		if amtStr == "" {
			amtStr = "0"
		}
		clean := ""
		for _, ch := range amtStr {
			if ch >= '0' && ch <= '9' {
				clean += string(ch)
			}
		}
		if clean == "" {
			clean = "0"
		}
		n, _ := decimal.NewFromString(clean)
		ledgerRec.BrAmt = decimal.New(n.IntPart(), -2)
		WsEofFlag = "N"
		// this was last line, next will be EOF
		pendingEOF = true
		eofReached = true // after this, next read will be done
		// Actually we need to not set eofReached yet? But we have consumed last line; next call should report EOF.
		// So set pending to true and keep eofReached false until next call.
		// Let's revert: we set pendingEOF true, eofReached false, so next call will try read and get empty.
		eofReached = false
		return
	}
	line = strings.TrimRight(line, "\r\n")
	if len(line) < 14 {
		line = line + strings.Repeat(" ", 14-len(line))
	} else if len(line) > 14 {
		line = line[:14]
	}
	ledgerRec.BrBranch = line[0:2]
	ledgerRec.BrAcct = line[2:6]
	ledgerRec.BrType = line[6:7]
	amtStr := line[7:14]
	amtStr = strings.TrimSpace(amtStr)
	if amtStr == "" {
		amtStr = "0"
	}
	clean := ""
	for _, ch := range amtStr {
		if ch >= '0' && ch <= '9' {
			clean += string(ch)
		}
	}
	if clean == "" {
		clean = "0"
	}
	n, _ := decimal.NewFromString(clean)
	ledgerRec.BrAmt = decimal.New(n.IntPart(), -2)
	WsEofFlag = "N"
}

// we will use a simpler reader implementation
var lines []string
var lineIdx int

func loadLines() {
	data, err := os.ReadFile("input.dat")
	if err != nil {
		lines = []string{}
		return
	}
	// split by lines (\n) preserving possible \r
	// COBOL LINE SEQUENTIAL: one record per line
	raw := string(data)
	// Use strings.Split after normalizing
	raw = strings.ReplaceAll(raw, "\r\n", "\n")
	raw = strings.ReplaceAll(raw, "\r", "\n")
	if raw == "" {
		lines = []string{}
		return
	}
	parts := strings.Split(raw, "\n")
	// If file ends with newline, Split gives trailing empty string; that should not be a record.
	if len(parts) > 0 && parts[len(parts)-1] == "" {
		parts = parts[:len(parts)-1]
	}
	lines = parts
}

func READ_PARA() {
	if lineIdx >= len(lines) {
		WsEofFlag = "Y"
		return
	}
	line := lines[lineIdx]
	lineIdx++
	if len(line) < 14 {
		line = line + strings.Repeat(" ", 14-len(line))
	} else if len(line) > 14 {
		line = line[:14]
	}
	ledgerRec.BrBranch = line[0:2]
	ledgerRec.BrAcct = line[2:6]
	ledgerRec.BrType = line[6:7]
	amtStr := line[7:14]
	// trim spaces
	amtTrim := strings.TrimSpace(amtStr)
	if amtTrim == "" {
		amtTrim = "0"
	}
	clean := ""
	for _, ch := range amtTrim {
		if ch >= '0' && ch <= '9' {
			clean += string(ch)
		}
	}
	if clean == "" {
		clean = "0"
	}
	n, _ := decimal.NewFromString(clean)
	ledgerRec.BrAmt = decimal.New(n.IntPart(), -2)
	WsEofFlag = "N"
}

func isInputDone() bool {
	return WsEofFlag == "Y"
}
func isFirstRecord() bool {
	return WsFirstFlag == "Y"
}

func POST_PARA() {
	WsAmtEd = formatAmt(ledgerRec.BrAmt)
	switch ledgerRec.BrType {
	case "D":
		WsBal = WsBal.Add(ledgerRec.BrAmt)
		fmt.Printf("%s D %s\n", ledgerRec.BrAcct, WsAmtEd)
	case "C":
		WsBal = WsBal.Sub(ledgerRec.BrAmt)
		fmt.Printf("%s C %s\n", ledgerRec.BrAcct, WsAmtEd)
	default:
		WsSkipped++
		// PIC 99 overflow handling: keep low-order 2 digits
		if WsSkipped > 99 {
			WsSkipped = WsSkipped % 100 // simplistic low-order digits (for 100 -> 0)
			// actually for >99, low-order 2 digits
		}
		fmt.Printf("%s ? SKIPPED\n", ledgerRec.BrAcct)
	}
}

func ACCT_BREAK_PARA() {
	WsBalEd = formatBal(WsBal)
	fmt.Printf("  ACCOUNT %s BALANCE:%s\n", WsPrevAcct, WsBalEd)
	WsBranchTot = WsBranchTot.Add(WsBal)
	WsBal = decimal.New(0, 0)
}

func BRANCH_BREAK_PARA() {
	WsTotEd = formatTot(WsBranchTot)
	fmt.Printf(" BRANCH %s TOTAL:%s\n", WsPrevBranch, WsTotEd)
	WsGrandTot = WsGrandTot.Add(WsBranchTot)
	WsBranchTot = decimal.New(0, 0)
}

func GRAND_PARA() {
	WsTotEd = formatTot(WsGrandTot)
	fmt.Printf("GRAND TOTAL:%s\n", WsTotEd)
	fmt.Printf("SKIPPED: %s\n", formatSkipped(WsSkipped))
}

func PROCESS_PARA() {
	if isFirstRecord() {
		WsPrevBranch = ledgerRec.BrBranch
		WsPrevAcct = ledgerRec.BrAcct
		WsFirstFlag = "N"
	} else {
		if ledgerRec.BrBranch != WsPrevBranch {
			ACCT_BREAK_PARA()
			BRANCH_BREAK_PARA()
			WsPrevBranch = ledgerRec.BrBranch
			WsPrevAcct = ledgerRec.BrAcct
		} else {
			if ledgerRec.BrAcct != WsPrevAcct {
				ACCT_BREAK_PARA()
				WsPrevAcct = ledgerRec.BrAcct
			}
		}
	}
	POST_PARA()
	READ_PARA()
}

func main() {
	WsEofFlag = "N"
	WsFirstFlag = "Y"
	WsPrevBranch = strings.Repeat(" ", 2)
	WsPrevAcct = strings.Repeat(" ", 4)
	WsBal = decimal.New(0, 0)
	WsBranchTot = decimal.New(0, 0)
	WsGrandTot = decimal.New(0, 0)
	WsSkipped = 0

	loadLines()
	lineIdx = 0
	READ_PARA()
	for !isInputDone() {
		PROCESS_PARA()
	}
	if !isFirstRecord() {
		ACCT_BREAK_PARA()
		BRANCH_BREAK_PARA()
	}
	GRAND_PARA()
}
